css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; display: grid; place-items: center; border-radius: 50%; background: color-mix(in srgb, #fff 66%, var(--accent-2)); box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 14%, var(--accent-2)); }
.loader::after { content: ''; position: absolute; width: 22%; height: 22%; border-radius: 50%; background: radial-gradient(circle at 38% 32%, color-mix(in srgb, #fff 30%, var(--accent-2)), color-mix(in srgb, #000 30%, var(--accent-2))); }
.loader .arms { position: relative; width: 100%; height: 100%; animation: ratchet calc(var(--loader-speed) * 2.7) cubic-bezier(.5, 0, .18, 1) infinite; }
.loader .arms span { position: absolute; top: 50%; left: 50%; width: 46%; height: 7%; margin-top: -3.5%; border-radius: 999px; transform-origin: left center; background: linear-gradient(90deg, var(--accent), color-mix(in srgb, #000 20%, var(--accent))); }
.loader .arms span:nth-child(2) { transform: rotate(120deg); }
.loader .arms span:nth-child(3) { transform: rotate(240deg); }
@keyframes ratchet { 0%, 16% { transform: rotate(0deg); } 33%, 49% { transform: rotate(120deg); } 66%, 82% { transform: rotate(240deg); } 100% { transform: rotate(360deg); } }
